def solve():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    n, k = map(int, input[ptr:ptr+2])
    ptr += 2
    d = list(input[ptr])
    ptr += 1

    for _ in range(k):
        found = False
        for i in range(n-1):
            if d[i] == '4' and d[i+1] == '7':
                found = True
                if (i+1) % 2 == 1:
                    d[i] = d[i+1] = '4'
                else:
                    d[i] = d[i+1] = '7'
                break
        if not found:
            continue

    print(''.join(d))

solve()
